From a5bc81d406abd174e1779253e8dc3c0accf7dd17 Mon Sep 17 00:00:00 2001
From: Jon Simons <jon@jonsimons.org>
Date: Fri, 14 Jul 2017 15:34:10 -0400
Subject: [PATCH] wrapper: fix gcrypt build error in ssh_cipher_clear

Fix a gcrypt build error introduced with
48e7b098f86207f8596651b5ba8242a3b834a868.

The ssh_cipher_struct only contains a `ctx` field on
the libcrypto builds, so it can't be referenced unless
within HAVE_LIBCRYPTO.

This build fix preserves the original spirit of the
change in 48e7b098f86207f8596651b5ba8242a3b834a868:
only call `EVP_CIPHER_CTX_free` when `cipher->ctx`
is non-NULL.

Signed-off-by: Jon Simons <jon@jonsimons.org>
Reviewed-by: Andreas Schneider <asn@cryptomilk.org>

diff --git a/src/wrapper.c b/src/wrapper.c
index 60dc9fd1..8f30aeba 100644
--- a/src/wrapper.c
+++ b/src/wrapper.c
@@ -120,14 +120,16 @@ void ssh_cipher_clear(struct ssh_cipher_struct *cipher){
         SAFE_FREE(cipher->key);
     }
 #endif
-    if (cipher->ctx != NULL) {
-        if (cipher->cleanup != NULL) {
-            cipher->cleanup(cipher);
-        }
+
+    if (cipher->cleanup != NULL) {
+        cipher->cleanup(cipher);
+    }
+
 #ifdef HAVE_LIBCRYPTO
+    if (cipher->ctx != NULL) {
         EVP_CIPHER_CTX_free(cipher->ctx);
-#endif
     }
+#endif
 }

 static void cipher_free(struct ssh_cipher_struct *cipher) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an incorrect assumption that the `ssh_cipher_struct` would always have a `ctx` field available, leading to a potential dereference of a NULL pointer when `EVP_CIPHER_CTX_free` was called without checking if `cipher->ctx` was non-NULL. This issue arose specifically in the context of builds that do not include the `HAVE_LIBCRYPTO` macro, where the `ctx` field is not present.

        Commit message:
        wrapper: fix gcrypt build error in ssh_cipher_clear

Fix a gcrypt build error introduced with
48e7b098f86207f8596651b5ba8242a3b834a868.

The ssh_cipher_struct only contains a `ctx` field on
the libcrypto builds, so it can't be referenced unless
within HAVE_LIBCRYPTO.

This build fix preserves the original spirit of the
change in 48e7b098f86207f8596651b5ba8242a3b834a868:
only call `EVP_CIPHER_CTX_free` when `cipher->ctx`
is non-NULL.

Signed-off-by: Jon Simons <jon@jonsimons.org>
Reviewed-by: Andreas Schneider <asn@cryptomilk.org>  

        Patch:

 void ssh_cipher_clear(struct ssh_cipher_struct *cipher){
 #ifdef HAVE_LIBGCRYPT
     unsigned int i;
 #endif

     if (cipher == NULL) {
         return;
     }

 #ifdef HAVE_LIBGCRYPT
     if (cipher->key) {
         for (i = 0; i < (cipher->keylen / sizeof(gcry_cipher_hd_t)); i++) {
             gcry_cipher_close(cipher->key[i]);
         }
         SAFE_FREE(cipher->key);
     }
 #endif
-    if (cipher->ctx != NULL) {
-        if (cipher->cleanup != NULL) {
-            cipher->cleanup(cipher);
-        }
+
+    if (cipher->cleanup != NULL) {
+        cipher->cleanup(cipher);
+    }
+
 #ifdef HAVE_LIBCRYPTO
+    if (cipher->ctx != NULL) {
         EVP_CIPHER_CTX_free(cipher->ctx);
-#endif
     }
+#endif
 }



